<main class="page beauty-selection-page"><section class="breadcrums"><div class="breadcrums__container _container"><div class="breadcrums__list"><div class="breadcrums__item"><a href="/<?= $lclang ?>" class="breadcrums__link"><?= $home_bc_title ?></a></div><div class="breadcrums__item"><a href="/<?= $lclang ?>/beauty-selections" class="breadcrums__link"><?= $lclang === 'ro' ? 'Selecții de frumusețe' : 'Бьюти-подборки' ?></a></div><div class="breadcrums__item"><span class="breadcrums__link"><?= htmlspecialchars($selection->title, ENT_QUOTES, 'UTF-8') ?></span></div></div></div></section>
